* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  min-height: 100vh;
  font-family: var(--font-sans);
  color: var(--text);
  background:
    radial-gradient(circle at 10% -10%, rgba(54, 245, 162, 0.13), transparent 28rem),
    radial-gradient(circle at 88% 8%, rgba(56, 216, 255, 0.14), transparent 30rem),
    linear-gradient(180deg, #0d1117 0%, #0a0e14 48%, #080b10 100%);
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: linear-gradient(to bottom, rgba(0,0,0,0.9), transparent 80%);
}

a { color: inherit; text-decoration: none; }
button, input { font: inherit; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  backdrop-filter: blur(18px);
  background: rgba(8, 11, 16, 0.78);
  border-bottom: 1px solid var(--border);
}
.nav {
  max-width: 1180px;
  margin: 0 auto;
  padding: 14px 22px;
  display: flex;
  align-items: center;
  gap: 18px;
}
.logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  letter-spacing: -0.03em;
  white-space: nowrap;
}
.logo-mark {
  width: 30px;
  height: 30px;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--primary), var(--primary-2));
  box-shadow: 0 0 30px rgba(54,245,162,0.25);
  display: grid;
  place-items: center;
  color: #05110c;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: 14px;
  flex: 1;
}
.nav-links a, .utility-btn {
  color: var(--muted);
  padding: 9px 11px;
  border-radius: 999px;
  transition: 180ms ease;
  font-size: 14px;
}
.nav-links a:hover, .nav-links a.active, .utility-btn:hover {
  color: var(--text);
  background: rgba(255,255,255,0.07);
}
.nav-actions { display: flex; align-items: center; gap: 8px; }
.utility-btn {
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.04);
  cursor: pointer;
}
.mobile-menu { display: none; }

.container { max-width: 1180px; margin: 0 auto; padding: 0 22px; }
.hero { padding: 86px 0 48px; }
.hero-grid { display: grid; grid-template-columns: minmax(0, 1.08fr) minmax(300px, 0.92fr); gap: 42px; align-items: center; }
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--primary);
  border: 1px solid rgba(54,245,162,0.24);
  background: rgba(54,245,162,0.08);
  border-radius: 999px;
  padding: 8px 12px;
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 22px;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.045em; }
h1 { font-size: clamp(44px, 8vw, 84px); line-height: 0.93; }
h2 { font-size: clamp(30px, 4.2vw, 52px); line-height: 1.02; }
h3 { font-size: 22px; line-height: 1.15; }
p { color: var(--muted); line-height: 1.7; }
.hero p { font-size: 18px; max-width: 740px; }
.gradient-text { background: linear-gradient(90deg, #fff, #aef8d3 45%, #9eeaff); -webkit-background-clip: text; color: transparent; }
.hero-actions, .button-row { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 28px; }
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 42px;
  padding: 11px 16px;
  border-radius: 999px;
  border: 1px solid var(--border-strong);
  color: var(--soft);
