  transition: transform 160ms ease, border-color 160ms ease, background 160ms ease, color 160ms ease;
}
.btn:hover { transform: translateY(-2px); border-color: rgba(56,216,255,0.45); color: var(--text); background: rgba(255,255,255,0.075); }
.btn.primary { color: #04100b; background: linear-gradient(135deg, var(--primary), var(--primary-2)); border: 0; font-weight: 800; }
.btn.small { min-height: 34px; padding: 8px 12px; font-size: 13px; }

