}
.hero-panel { border-radius: 28px; padding: 18px; }
.terminal-bar { display: flex; gap: 7px; padding: 9px 10px 14px; }
.dot { width: 10px; height: 10px; border-radius: 999px; background: var(--danger); }
.dot:nth-child(2) { background: var(--warning); }
.dot:nth-child(3) { background: var(--primary); }
pre, code { font-family: var(--font-mono); }
pre { margin: 0; overflow-x: auto; }
.code-body {
  border-radius: 18px;
  background: rgba(2, 6, 12, 0.72);
  border: 1px solid rgba(255,255,255,0.08);
  padding: 18px;
  color: #d5ffe9;
  font-size: 13px;
  line-height: 1.75;
}
.token-muted { color: #718096; }
.token-green { color: var(--primary); }
.token-cyan { color: var(--primary-2); }

.section { padding: 58px 0; }
.section-head { max-width: 760px; margin-bottom: 24px; }
.section-head p { font-size: 17px; }
.grid { display: grid; gap: 16px; }
.grid.three { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid.two { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid.four { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.product-card, .doc-card, .resource-card, .support-card {
