  padding: 24px;
  min-height: 100%;
  position: relative;
  overflow: hidden;
}
.product-card::before, .resource-card::before, .support-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 20% 0%, var(--glow, rgba(54,245,162,0.18)), transparent 18rem);
  opacity: 0.9;
  pointer-events: none;
}
.card-content { position: relative; z-index: 1; }
.icon-chip {
  width: 42px; height: 42px; border-radius: 14px;
  display: grid; place-items: center;
  margin-bottom: 18px;
  color: #06110c;
  background: linear-gradient(135deg, var(--chip, var(--primary)), #fff);
  font-weight: 900;
}
.card-link { color: var(--primary); font-weight: 800; display: inline-flex; margin-top: 10px; }
.doc-card:hover, .product-card:hover, .resource-card:hover { border-color: rgba(54,245,162,0.36); transform: translateY(-2px); }
.doc-card, .product-card, .resource-card { transition: 180ms ease; }

.cli-shell { border-radius: 30px; padding: 20px; }
.cli-layout { display: grid; grid-template-columns: 0.86fr 1.14fr; gap: 18px; }
.accordion-list { display: grid; gap: 10px; }
