.accordion-trigger {
  width: 100%;
  padding: 17px 18px;
  border: 0;
  background: transparent;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  text-align: left;
  font-weight: 800;
}
.accordion-trigger span:last-child { transition: transform 180ms ease; color: var(--primary); }
.accordion-item.open .accordion-trigger span:last-child { transform: rotate(45deg); }
.accordion-panel { max-height: 0; overflow: hidden; transition: max-height 240ms ease; }
.accordion-item.open .accordion-panel { max-height: 460px; }
.accordion-panel-inner { padding: 0 18px 18px; color: var(--muted); }
.accordion-panel ol { margin: 0; padding-left: 20px; line-height: 1.8; }
.tabs { display: inline-flex; padding: 4px; gap: 4px; border: 1px solid var(--border); background: rgba(255,255,255,0.04); border-radius: 999px; margin-bottom: 14px; }
.tab {
  border: 0;
  background: transparent;
  color: var(--muted);
  padding: 8px 12px;
  border-radius: 999px;
  cursor: pointer;
  transition: 160ms ease;
}
.tab.active { background: rgba(54,245,162,0.14); color: var(--primary); }
.command-label { color: var(--muted); font-size: 12px; margin: 12px 0 8px; text-transform: uppercase; letter-spacing: 0.12em; }
.copy-line { color: #d5ffe9; white-space: pre; }

.launch-card { border-radius: 28px; padding: 26px; background: linear-gradient(135deg, rgba(54,245,162,0.10), rgba(56,216,255,0.07)); border: 1px solid var(--border); }

.docs-layout {
  max-width: 1280px;
  margin: 0 auto;
  padding: 26px 22px 0;
  display: grid;
  grid-template-columns: 286px minmax(0, 1fr);
  gap: 26px;
}
.sidebar {
  position: sticky;
  top: 78px;
  height: calc(100vh - 100px);
  border: 1px solid var(--border);
  background: rgba(8, 11, 16, 0.72);
  border-radius: 24px;
  padding: 16px;
  transition: width 220ms ease, padding 220ms ease, opacity 220ms ease;
  overflow: hidden;
}
.sidebar-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
.collapse-btn { border: 1px solid var(--border); background: rgba(255,255,255,0.05); color: var(--soft); border-radius: 12px; padding: 8px 10px; cursor: pointer; }
.sidebar nav { display: grid; gap: 6px; }
.sidebar a { color: var(--muted); border-radius: 12px; padding: 10px 11px; font-size: 14px; }
.sidebar a:hover, .sidebar a.active { background: rgba(255,255,255,0.06); color: var(--text); }
.docs-layout.sidebar-collapsed { grid-template-columns: 76px minmax(0, 1fr); }
.docs-layout.sidebar-collapsed .sidebar { padding: 14px 10px; }
.docs-layout.sidebar-collapsed .sidebar-title, .docs-layout.sidebar-collapsed .sidebar nav, .docs-layout.sidebar-collapsed .collapse-label { display: none; }
.docs-layout.sidebar-collapsed .collapse-btn { width: 100%; }
.doc-main { min-width: 0; }
.doc-hero { padding: 48px 0 28px; }
.doc-section { padding: 36px 0; border-top: 1px solid var(--border); }
.card-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; margin-top: 20px; }
.card-grid.two { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.card-grid.four { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.kicker { color: var(--primary); text-transform: uppercase; font-size: 12px; letter-spacing: 0.16em; font-weight: 900; margin-bottom: 10px; }
.badge { display: inline-flex; color: var(--primary); border: 1px solid rgba(54,245,162,0.25); border-radius: 999px; padding: 5px 9px; background: rgba(54,245,162,0.08); font-size: 12px; font-weight: 800; }

.actor-diagram { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-top: 22px; }
.actor { border-radius: 22px; padding: 22px; text-align: center; background: rgba(255,255,255,0.045); border: 1px solid var(--border); }
.actor strong { display: block; font-size: 28px; margin-bottom: 8px; color: var(--primary); letter-spacing: -0.04em; }
.flow-steps { counter-reset: steps; display: grid; gap: 12px; margin-top: 20px; }
.flow-step { counter-increment: steps; display: grid; grid-template-columns: 42px 1fr; gap: 14px; align-items: start; padding: 18px; border-radius: 18px; background: rgba(255,255,255,0.04); border: 1px solid var(--border); }
.flow-step::before { content: counter(steps); width: 34px; height: 34px; border-radius: 12px; display: grid; place-items: center; background: rgba(56,216,255,0.13); color: var(--primary-2); font-weight: 900; }

.footer { margin-top: 56px; border-top: 1px solid var(--border); background: rgba(2,6,12,0.42); }
.footer-grid { max-width: 1180px; margin: 0 auto; padding: 38px 22px; display: grid; grid-template-columns: 1.2fr repeat(4, 1fr); gap: 24px; }
.footer h4 { margin: 0 0 12px; }
.footer a { display: block; color: var(--muted); margin: 9px 0; font-size: 14px; }
.footer a:hover { color: var(--primary); }

.fade-in { animation: fadeIn 520ms ease both; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: translateY(0); } }

@media (max-width: 940px) {
  .mobile-menu { display: inline-flex; }
  .nav { flex-wrap: wrap; }
  .nav-links { order: 3; display: none; width: 100%; margin-left: 0; padding-top: 10px; flex-wrap: wrap; }
  .nav-links.open { display: flex; }
  .nav-actions { margin-left: auto; }
  .hero-grid, .cli-layout, .grid.three, .grid.two, .grid.four, .footer-grid, .card-grid, .card-grid.two, .card-grid.four, .actor-diagram { grid-template-columns: 1fr; }
